def main():
 d=pd.read_csv(SRC,low_memory=False); rows=[]
 for _,r in d.iterrows():
  y=int(r['TIME_PERIOD']); rows.append({'pattern_id':f"OECD_PMR_{r['IND']}_ARCHIVE2013_V1",'domain':'institutions_policy','entity_id':str(r['COU']),'entity_name':r['Country'],'timestamp':y,'native_frequency':'source_defined_wave','state_label':'regulatory_indicator_observed','state_probability':None,'source_observations':{'indicator_id':r['IND'],'indicator_name':r['Indicator'],'value_raw':float(r['OBS_VALUE']),'obs_status':r['OBS_STATUS'],'unit_measure':None if pd.isna(r['UNIT_MEASURE']) else r['UNIT_MEASURE'],'unit_multiplier':None if pd.isna(r['UNIT_MULT']) else r['UNIT_MULT'],'base_period':None if pd.isna(r['BASE_PER']) else r['BASE_PER']},'lead_profile':{},'uncertainty':['PMR 2013 archive vintage','wave observations are not annual','no policy shock date inferred','no leader-specific deviation inferred'],'failure_cases':['no interpolation between waves','no annual continuity assumed','no composite score created','no causal claim'],'edge_status':'not_testable','evidence_refs':['raw/oecd_pmr_2013/OECD_DF_PMR_UNFILTERED.csv','OECD_PMR_RAW_PROFILE_V1.json']})
 out=OUT/'OECD_PMR_DOMAIN_STATES_SOURCE_WAVES_V1.jsonl'; out.write_text(''.join(json.dumps(x,ensure_ascii=False)+'\n' for x in rows)); summary={'adapter_id':'OECD_PMR_ARCHIVE_DOMAIN_STATE_ADAPTER_V1','input':str(SRC.relative_to(ROOT)),'input_sha256':hashlib.sha256(SRC.read_bytes()).hexdigest(),'records':len(rows),'entities':int(d.COU.nunique()),'indicators':int(d.IND.nunique()),'years':sorted(pd.to_numeric(d.TIME_PERIOD).astype(int).unique().tolist()),'native_frequency':'source_defined_wave','raw_modified':False,'interpolation':False,'imputation':False,'source_averaging':False,'composite_created':False,'status':'source_native_states_ready_not_annual'}; (OUT/'OECD_PMR_DOMAIN_ADAPTER_SUMMARY_V1.json').write_text(json.dumps(summary,ensure_ascii=False,indent=2)+'\n'); print(json.dumps(summary,ensure_ascii=False,indent=2))
